def quote(price, n=0, status="open"):
    terms = {"unit_price": price, "payment_days": 30, "lead_time_days": 35, "incoterm": "FCA", "contract_months": 12,
             "effective_date": "2026-11-01"}
    return {"from": f"sales@{F1}", "status": status, "body": "Our offer.", "attachments": [],
            "term_sheets": [{"term_sheet_id": f"offer:{F1}-{n}", "terms": terms}]}


class Foundry:
    """One supplier: concedes 1 % a round for `moves` rounds, then repeats its price (a stall)."""

    def __init__(self, moves=5):
        self.moves, self.sent, self.log, self.lock = moves, 0, [], threading.Lock()

    def _ctx(self):
        pass

    def open_session(self, case_id):
        return {"session_id": "s1", "case": CASE, "threads": {F1: [quote(52.90)]}}

    def attachment(self, session_id, attachment_id):
        return b""

    def session(self, session_id):
        return {"status": "open"}

    def thread(self, session_id, supplier_id):
        raise AssertionError("no resync expected")

    def send_message(self, session_id, sup, msg):
        if msg.get("action"):
            self.log.append(("accept", self.sent))
            return {"result": {"deal": True, "supplier_id": sup, "score": 0.5, "terms": {}}}
        self.sent += 1
        asks = [s["terms"]["unit_price"] for s in msg.get("term_sheets") or []]
        self.log.append(("ask", self.sent, asks))
        k = min(self.sent, self.moves)
        return quote(round(52.90 * (1 - 0.01 * k), 2), n=self.sent)


def run(cfg, moves=5):
