def test_keeps_negotiating_while_facts_land_and_never_sends_an_id_twice():
    frozen, _ = run(replace(VARIANTS["A9h"][1]))
    plan, res = run(PLAN)
    assert res["deal"]
    assert len(plan.refs) == len(set(plan.refs))  # no ID twice
