"""The a9h-practice run from the event log: per case the score, deal, rounds, timing, failures, and the comparison
with Tugra's A9 run (18:15) and the team's best before this run."""
import json
import sys
from collections import defaultdict

VARIANT = sys.argv[1] if len(sys.argv) > 1 else "a9h-practice"
A9 = {"P01": 0.956, "P02": 0.360, "P03": 0.923, "P04": 0.810, "P05": 0.665, "P07": 0.710, "P08": 0.586, "P10": 0.671,
      "P11": 0.710, "P18": 0.485}
BEST_BEFORE = {"P01": 0.956, "P02": 0.684, "P03": 0.923, "P04": 0.874, "P05": 0.665, "P07": 0.710, "P08": 0.603,
               "P10": 0.679, "P11": 0.710, "P18": 0.532}
ev = [json.loads(l) for l in open("/Users/ardagurses/Desktop/TactoEHL/logs/events.jsonl")]
runv = {e["run"]: e.get("variant") for e in ev if e.get("kind") == "run"}
S = defaultdict(lambda: {"msgs": 0, "score": None, "deal": None, "terms": None, "gaps": [], "took": [], "steps": [],
                         "warn": [], "lb": {}, "final_at": None, "accept_lag": None, "t0": None, "t1": None, "end": None})
for e in ev:
    if runv.get(e.get("run")) != VARIANT or not e.get("case"):
        continue
    s = S[e["case"][5:]]
    s["t0"] = s["t0"] or e["ts"]; s["t1"] = e["ts"]
    k = e["kind"]
    if k == "buyer":
        s["msgs"] += 1; s["lb"][e["supplier"]] = e["ts"]
    elif k == "supplier" and e.get("took") is not None:
        s["took"].append(e["took"]); s["gaps"].append(round(e["ts"] - s["lb"].get(e["supplier"], e["ts"]) - e["took"], 1))
        if e.get("status") in ("final_offer", "agreed"):
            s["final_at"] = e["ts"]
    elif k == "action" and s["final_at"]:
        s["accept_lag"] = round(e["ts"] - s["final_at"], 1)
    elif k == "result":
        s["score"], s["deal"], s["terms"], s["end"] = e.get("score"), e.get("supplier"), e.get("terms") or {}, e.get("end_reason")
    elif k == "warning":
        s["warn"].append((e.get("message") or "")[:90])
    elif k in ("engine", "plan") and (e.get("step") or e.get("move")) not in ("send", "route", "target", "stagger"):
        s["steps"].append(e.get("step") or e.get("move"))
print(f"{'case':<5}{'A9h':>6}{'A9':>7}{'best':>7} {'deal':<36} {'msgs':>4} {'min':>5} {'reply s':>8} {'maxgap':>6} {'lag':>5}  steps")
tot = []
for cid in sorted(S):
    s = S[cid]; t = s["terms"] or {}
    deal = f"{s['deal'] or '-'} €{t.get('unit_price')} pay{t.get('payment_days')} {t.get('contract_months')}m lead{t.get('lead_time_days')}" + (" clause" if t.get("index_clause") else "")
    sc = s["score"]
    if sc is not None:
        tot.append(sc)
    print(f"{cid:<5}{(sc if sc is not None else 0):>6.3f}{A9.get(cid, 0):>7.3f}{BEST_BEFORE.get(cid, 0):>7.3f} {deal[:36]:<36} {s['msgs']:>4} {(s['t1'] - s['t0']) / 60:>5.1f} "
          f"{(max(s['took']) if s['took'] else 0):>8.1f} {(max(s['gaps']) if s['gaps'] else 0):>6.1f} {str(s['accept_lag']):>5}  {s['steps'][:6]} {s['warn'][:2]} {s['end'] or ''}")
if tot:
    print(f"\nmean {sum(tot) / len(tot):.3f} over {len(tot)} cases (A9 run: {sum(A9.values()) / len(A9):.3f}; team best before: {sum(BEST_BEFORE.values()) / len(BEST_BEFORE):.3f})")
    new = [c for c in S if S[c]["score"] is not None and S[c]["score"] > BEST_BEFORE.get(c, 0) + 0.001]
    print("new team bests:", new)

