"""Side by side: per case score of several practice variants from the event log, with means and LLM stats."""
import json
import statistics
import sys
from collections import defaultdict

VARS = sys.argv[1:]
ev = [json.loads(l) for l in open("/Users/ardagurses/Desktop/TactoEHL/logs/events.jsonl")]
runv = {e["run"]: e.get("variant") for e in ev if e.get("kind") == "run"}
score, llm, fb, rounds = defaultdict(dict), defaultdict(list), defaultdict(int), defaultdict(dict)
for e in ev:
    v = runv.get(e.get("run"))
    if v not in VARS or not e.get("case"):
        continue
    c = e["case"][5:]
    if e["kind"] == "result" and e.get("score") is not None:
        score[v][c] = e["score"]
    elif e["kind"] == "buyer":
        rounds[v][c] = rounds[v].get(c, 0) + 1
    elif e["kind"] == "llm" and e.get("ok"):
        llm[v].append(e.get("took") or 0)
    elif e["kind"] == "warning" and "engine writer" in (e.get("message") or ""):
        fb[v] += 1
cases = sorted({c for v in VARS for c in score[v]})
print(f"{'case':<6}" + "".join(f"{v:>14}" for v in VARS))
