"""Patience with movement: an open supplier that still concedes is asked again, a little below its offer; the first
stalled reply is taken; a final offer is taken at once."""

import json
import threading
from dataclasses import replace
from pathlib import Path

import proto.engine as eng
from proto.variants import VARIANTS

CASE = json.loads((Path(__file__).resolve().parents[1] / "cases" / "D01.json").read_text(encoding="utf-8"))
F1 = "sup:DEMO-F1"


def quote(price, n=0, status="open"):
    terms = {"unit_price": price, "payment_days": 30, "lead_time_days": 35, "incoterm": "FCA", "contract_months": 12,
             "effective_date": "2026-11-01"}
    return {"from": f"sales@{F1}", "status": status, "body": "Our offer.", "attachments": [],
            "term_sheets": [{"term_sheet_id": f"offer:{F1}-{n}", "terms": terms}]}


class Foundry:
    """One supplier: concedes 1 % a round for `moves` rounds, then repeats its price (a stall)."""

    def __init__(self, moves=5):
        self.moves, self.sent, self.log, self.lock = moves, 0, [], threading.Lock()

    def _ctx(self):
        pass

    def open_session(self, case_id):
        return {"session_id": "s1", "case": CASE, "threads": {F1: [quote(52.90)]}}

    def attachment(self, session_id, attachment_id):
        return b""

    def session(self, session_id):
        return {"status": "open"}

    def thread(self, session_id, supplier_id):
        raise AssertionError("no resync expected")

    def send_message(self, session_id, sup, msg):
        if msg.get("action"):
            self.log.append(("accept", self.sent))
            return {"result": {"deal": True, "supplier_id": sup, "score": 0.5, "terms": {}}}
        self.sent += 1
        asks = [s["terms"]["unit_price"] for s in msg.get("term_sheets") or []]
        self.log.append(("ask", self.sent, asks))
        k = min(self.sent, self.moves)
        return quote(round(52.90 * (1 - 0.01 * k), 2), n=self.sent)


def run(cfg, moves=5):
    foundry = Foundry(moves)
    res = eng.Negotiator(foundry, "case:D01", cfg, quiet=True).run()
    return foundry, res


def test_patient_keeps_asking_while_it_moves_and_takes_the_first_stall():
    base = replace(VARIANTS["A10"][1], rfq_pushes=0)
    foundry, res = run(base, moves=5)
    assert res["deal"] and foundry.sent == 6  # five concessions answered, the first repeated price taken
    asks = [a for k, _, a in foundry.log if k == "ask"]
    assert all(min(asks[i]) != min(asks[i - 1]) for i in range(1, len(asks)))  # never the same ask twice
    accept = next(n for k, n in foundry.log if k == "accept")
    assert accept == 6


def test_without_patience_the_curve_takes_the_offer_at_its_goal_earlier():
    frozen = replace(VARIANTS["A9h"][1], rfq_pushes=0)
    foundry, res = run(frozen, moves=5)
    patient, _ = run(replace(VARIANTS["A10"][1], rfq_pushes=0), moves=5)
    assert res["deal"] and foundry.sent < patient.sent

